	private bool IsIgnoreEggHatchCountZone(global::ZoneID zoneId) {
        if (zoneId >= ZoneID.UGAASECRETBASE01 && zoneId <= ZoneID.UGFASECRETBASE01)
            return true;
        if (zoneId >= ZoneID.UGSECRETBASE01 && zoneId <= ZoneID.UGSECRETBASE04)
            return true;
        if (zoneId == ZoneID.D11R0101)
            return true;
        return zoneId == ZoneID.UGFASECRETBASE02 || zoneId == ZoneID.UGFASECRETBASE03;
    }
	private void UpdateWalkCount() {
        if (currentSequence != SequenceID.SandClimbSucsess && currentSequence != SequenceID.SandFall && currentSequence != SequenceID.Active)
            return;

        if (IsIgnoreWalkCountZone(PlayerWork.zoneID))
            return;

        if (NoWalkUpdateAttribute())
            return;

        var delta = gridPosition - oldGridPosition;
        int steps = Mathf.Abs(delta.x) + Mathf.Abs(delta.y);

        if (PlayerWork.zoneID != ZoneID.UNKNOWN && GameManager.mapInfo[(int)PlayerWork.zoneID].MapType != MapType.MAPTYPE_UNDERGROUND &&
            !EvDataManager.Instanse.IsPosEventReserved && ItemWork.GetSprayCount() > 0)
        {
            ItemWork.SubSprayCount((short)steps);
            if (ItemWork.GetSprayCount() <= 0)
            {
                EvDataManager.Instanse.EndSpray();
                ItemWork.SetSpray(0, 0);
            }
        }

        PlayerWork.SafariStepCount -= steps;
        if (PlayerWork.SafariStepCount < 0)
            PlayerWork.SafariStepCount = 0;

        if (steps > 0)
        {
            AzukariyaWork.AddEggStep(steps);
            if (!IsIgnoreEggHatchCountZone(PlayerWork.zoneID))
                EvDataManager.Instanse.UpdatePartyEggHatchingCount(steps);

            PokeWork.WalkNatukiUpdate(steps);
        }

        FieldPoketch.CountPoketchPedometer(steps);

        byte prevCharge = PlayerWork.BtlSearcherCharge;
        PlayerWork.BtlSearcherCharge = (byte)(PlayerWork.BtlSearcherCharge + steps);
        if (prevCharge < 100 && PlayerWork.BtlSearcherCharge == 100)
            FieldBattleSearcher.WalkClearFlag();

        Dpr.Field.SwayGrass.SwayGrass_ChargePokeSearcher((byte)steps);

        if (IsEncount())
            PlayerWork.WalkEncountCount += steps;

        PlayReportManager.AddWalkCnt(steps);
    }
