	private void KairikiPushObject(float deltaTime) {
        float prevPushTime = KairikiPushTime;
        int prevPushIndex = KairikiPushObjectIndex;
        KairikiPushObjectIndex = -1;
        KairikiPushTime = 0.0f;

        if (!FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_KAIRIKI))
            return;

        if (EvDataManager.Instanse.IsRunningEvent())
            return;

        if (FieldManager.Instance.IsMenuOpen)
            return;

        if (FieldManager.Instance.isMenuOpenRequest)
            return;

        if (!PlayerWork.isPlayerInputActive)
            return;

        GetInputVectorIgnoreUpdateInputAngle(out Vector2 stickL, out float stickPowerSq, 0.0f, out bool analogstick);
        if (stickPowerSq <= 0.0f)
            return;

        if (!analogstick && !(InputMoveVector.x * GameController.digitalPad.x < 0.0f) && InputMoveVector.z * GameController.digitalPad.y >= 0.0f)
            return;

        DIR dir = GetDir(yawAngle);
        for (int i = 0; i < EvDataManager.Instanse._fieldObjectEntity.Count; i++)
        {
            var target = EvDataManager.Instanse._fieldObjectEntity[i];
            if (target == null || !target.EventParams.Kairiki)
                continue;

            if (Dpr.Field.WA_Kairiki.PushEntity(this, dir, target, out Vector2Int pushGrid, out bool hit))
            {
                GameManager.GetAttribute(pushGrid, out int code, out int stop);
                if (stop == 128)
                    continue;

                bool isBlocked = false;
                for (int j = 0; j < target.EventParams.NearObject.Length; j++)
                {
                    int nearIndex = target.EventParams.NearObject[j];
                    if (nearIndex == -10)
                        continue;

                    var near = EvDataManager.Instanse._fieldObjectEntity[nearIndex];
                    if (near == this || near == null || !near.gameObject.activeInHierarchy)
                        continue;

                    if (near.gridPosition.x == pushGrid.x && near.gridPosition.y == pushGrid.y)
                    {
                        isBlocked = true;
                        break;
                    }
                }

                if (isBlocked)
                    continue;

                KairikiPushObjectIndex = i;
                KairikiPushTime = prevPushTime + deltaTime;
                if (prevPushIndex == i)
                {
                    if (!(DataManager.GetFieldCommonParam(ParamIndx.Kairiki_PushTime) > KairikiPushTime))
                    {
                        StopCrossInputAndBicycle();
                        FlagWork.SetWork(EvWork.WORK_INDEX.WK_KAIRIKI_OBJ_ID, prevPushIndex);
                        FlagWork.SetWork(EvWork.WORK_INDEX.WK_KAIRIKI_OBJ_DIR, (int)dir);
                        EvDataManager.Instanse.JumpLabel("ev_kairiki_iwa_move", null);
                    }
                }
                else
                {
                    KairikiPushTime = 0.0f;
                }

                moveVector = Vector3.zero;
                return;
            }

            if (hit)
            {
                if (dir > DIR.DIR_DOWN)
                    moveVector.x = 0.0f;
                else
                    moveVector.z = 0.0f;
            }
        }
    }
	private void LimitHeight() {
        if ((object)FieldManager.Instance == null)
            return;
        if (PlayerWork.IsFormSwim())
            return;
        if (!isLanding)
            return;
        if (FieldManager.Instance.IsNoEntry(gridPosition, worldPosition))
            return;
        if (!GameManager.IsHighAttribute(GameManager.GetAttributeExCodeRaw(gridPosition), worldPosition.y))
            return;

        if (CollisionUtility.IsOverCollideGround(worldPosition, 0.5f, Layer.Ground))
        {
            moveVector.y = CollisionUtility.OverCollideGround(worldPosition, 0.0f, Layer.Ground, true);
            return;
        }

        Collider[] colliders = CollisionUtility.OverrapSphere(transform, new Vector3(0.0f, 0.5f, 0.0f), 0.0f, out int count, Layer.Ground);
        for (int i = 0; i < count; i++)
        {
            BoxCollider box = colliders[i] as BoxCollider;
            if (box)
            {
                float top = box.size.y * 0.5f + box.center.y + box.transform.position.y;
                if (moveVector.y < top)
                    moveVector.y = top;
            }
        }
    }
