	public void SetIceFloorDirty() {
        if (IceFloorDirtyNextDir != DIR.DIR_NOT)
            return;

        IceFloorDirtyNextDir = GetDir();
    }
	private bool CheckIceFloor(float deltaTime) {
        if (FieldPoketch.IsControlPoketch() && IceFloorDirtyNextDir == DIR.DIR_NOT)
            IceFloorDirtyNextDir = GetDir();

        if (currentSequence != SequenceID.Active || !PlayerWork.isPlayerInputActive)
            return false;

        Vector2Int grid = PositionToGrid(worldPosition + moveVector);
        // IsIceGrid never reads its height argument
        if (!IsIceGrid(grid, worldPosition.y))
            return false;

        Vector3 direction;
        if (IceFloorDirtyNextDir != DIR.DIR_NOT)
        {
            DIR dir = IceFloorDirtyNextDir;
            IceFloorDirtyNextDir = DIR.DIR_NOT;
            switch (dir)
            {
                case DIR.DIR_UP: direction = Vector3.back; break;
                case DIR.DIR_DOWN: direction = Vector3.forward; break;
                case DIR.DIR_LEFT: direction = Vector3.right; break;
                case DIR.DIR_RIGHT: direction = Vector3.left; break;
                default: return false;
            }

            Vector3 center = Vec2ToVec3Position(GridToPosition(grid), worldPosition.y);
            if (CollisionUtility.CollideGround(center + direction, 1.0f, Layer.Ground) > 0.1f)
                return false;
        }
        else if (grid != gridPosition)
        {
            Vector2 diff = GridToPosition(grid) - GridToPosition(gridPosition);
            direction = new Vector3(diff.x, 0.0f, (diff.y != 0.0f && diff.x != 0.0f) ? 0.0f : diff.y);
        }
        else
        {
            if (moveVector == Vector3.zero)
                return false;

            direction = CalcIceMoveDirection(moveVector);
            if (Vector3.Dot(InputMoveVector, direction) <= 0.0f)
                return false;
        }

        if (CheckColIceFloor(direction, DataManager.FieldCommonParam[(int)ParamIndx.IceFloorSpdLv1].param * deltaTime, out Vector3 outVelocity))
            return false;

        IceFloorDirection = direction;
        return true;
    }
	private global::UnityEngine.Vector3 CalcIceMoveDirection(global::UnityEngine.Vector3 inputVector) {
        if (inputVector.x * inputVector.x < inputVector.z * inputVector.z)
            return inputVector.z > 0.0f ? Vector3.forward : Vector3.back;
        else
            return inputVector.x > 0.0f ? Vector3.right : Vector3.left;
    }
	private void StartIceFloor() {
        PlayerWork.isPlayerInputActive = false;
        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI400, null);

        IceFloorState = IceFloorStateType.Slip;
        IceSlidingLevel = 1;
        IsIceSlope = false;
        IceFloorStopTime = 0.0f;
        IceSlidingSpeed = DataManager.GetFieldCommonParam(ParamIndx.IceFloorSpdLv1);
        IceFloorStartGridCenterPos = Vec2ToVec3Position(GridToPosition(oldGridPosition), worldPosition.y);

        float targetYaw = (float)Math.Atan2(IceFloorDirection.x, IceFloorDirection.z) * Mathf.Rad2Deg;
        IceSlidingRotate.FloatMove.EaseFunc = FieldFloatMove.EaseInOutSin;
        IceSlidingRotate.SetObjectEntity(this);
        IceSlidingRotate.MoveTime(targetYaw, 0.2f);

        IceSlopeDownMove.FloatMove.EaseFunc = FieldFloatMove.EaseInOutSin;
        IceSlopeDownMove.IgnoreY = true;
        IceSlopeDownMove.SetObjectEntity(this);

        Vector3 pos = worldPosition;
        int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
        pos[axis] = IceFloorStartGridCenterPos[axis];

        float groundNear = CollisionUtility.CollideGround(pos - IceFloorDirection * 0.15f, 30.0f, Layer.Ground);
        float groundFar = CollisionUtility.CollideGround(pos - IceFloorDirection * 0.25f, 30.0f, Layer.Ground);
        float diff = groundFar - groundNear;
        if (diff * diff > 0.001f * 0.001f)
            IsIceSlope = true;

        PlayIdle();
        nextSequence = SequenceID.IceFloor;
    }
	private void EndIceFloor() {
        PlayerWork.isPlayerInputActive = true;
        IceFloorState = IceFloorStateType.None;
        IceSlidingLevel = 0;
        IceSlidingRotate.Reset();
        IceSlopeDownMove.Reset();
        nextSequence = SequenceID.Active;
    }
	private void UpdateIceFloor(float deltaTime) {
        switch (IceFloorState)
        {
            case IceFloorStateType.SlopeDown:
                IceSlopeDownMove.Update(deltaTime);
                if (!IceSlopeDownMove.IsBusy)
                    EndIceFloor();
                break;

            case IceFloorStateType.Slip:
            {
                IceSlidingRotate.Update(deltaTime);
                float speed = UpdateIceSpeed(deltaTime);

                Vector3 direction = CalcAdjustIceFloorMoveDirection() * speed;
                int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
                direction[axis] *= 2.0f;
                float moveLength = direction.FastNormalize() * deltaTime;

                CheckColSnowBall(direction, moveLength);
                bool isHit = CheckColIceFloor(direction, moveLength, out Vector3 outVelocity);

                float heightDiff = worldPosition.y - beforePosition.y;
                if (IsIceSlope)
                {
                    if (heightDiff * heightDiff < 0.001f * 0.001f)
                        IsIceSlope = false;
                }
                else
                {
                    int axis2 = IceFloorDirection.x != 0.0f ? 2 : 0;
                    float center = IceFloorStartGridCenterPos[axis2];
                    float current = worldPosition[axis2];
                    Vector3 before = beforePosition;
                    float prev = before[axis2];

                    if (heightDiff * heightDiff > 0.001f * 0.001f &&
                        (center - current) * (center - current) < 0.49f * 0.49f &&
                        (center - prev) * (center - prev) < 0.49f * 0.49f)
                    {
                        if (heightDiff < 0.0f)
                        {
                            if (IceSlidingLevel <= 3)
                                IceSlidingLevel = IceSlidingLevel + 1;
                        }
                        else
                        {
                            int level = IceSlidingLevel - 1;
                            if (level >= 0)
                                IceSlidingLevel = level;
                        }

                        IsIceSlope = true;
                    }
                }

                moveVector = outVelocity;

#if PC_UNLOCKED_FPS
                if ((worldPosition - beforePosition).sqrMagnitude < 0.001f * 0.001f * PcPlatform.PcFrameClock.Frames * PcPlatform.PcFrameClock.Frames) // PC (s37): "did not move" = under 0.001 per 30 Hz frame
#else
                if ((worldPosition - beforePosition).sqrMagnitude < 0.001f * 0.001f)
#endif
                    IceFloorStopTime += deltaTime;

                // IsIceGrid never reads its height argument
                if (!IsIceGrid(gridPosition, worldPosition.y) || IceFloorStopTime > 0.06f)
                {
                    AudioManager.Instance.PlaySe(AK.EVENTS.STOP_SE, null);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI401, null);
                    EndIceFloor();
                }
                else if (IceSlidingLevel <= 0)
                {
                    CheckIceSlope();
                }

                if (IceFloorState == IceFloorStateType.Slip && isHit)
                {
                    AudioManager.Instance.PlaySe(AK.EVENTS.STOP_SE, null);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI402, null);
                    EndIceFloor();
                }
                break;
            }
        }
    }
	private global::UnityEngine.Vector3 CalcAdjustIceFloorMoveDirection() {
        Vector3 adjust = Vector3.zero;
        int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
        adjust[axis] = IceFloorStartGridCenterPos[axis] - worldPosition[axis];

        Vector3 direction = IceFloorDirection + adjust;
        direction.Normalize();
        return direction;
    }
	private void CheckColSnowBall(global::UnityEngine.Vector3 direction, float speed) {
        if (IceSlidingLevel < 2)
            return;

        var grid = PositionToGrid(worldPosition + direction * (speed + 0.5f));
        foreach (var entity in EntityManager.fieldObjects)
        {
            if (!entity.EventParams.SnowBall)
                continue;

            if (entity.gameObject != null && entity.gameObject.activeInHierarchy)
            {
                var entityGrid = entity.gridPosition;
                if (entityGrid.x == grid.x && entityGrid.y == grid.y)
                    CrashSnowBall(entity);
            }
        }
    }
	private void CrashSnowBall(global::FieldObjectEntity entity) {
        if (entity.EventParams.VanishFlagIndex < 1)
            return;

        EvDataManager.Instanse.SetFlag(entity.EventParams.VanishFlagIndex, true);
        entity.gameObject.SetActive(false);
        FieldManager.Instance.CallEffect(EffectFieldID.EF_F_BG_SNOWBALLBREAK_01, entity.transform, null, null);
        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI112, null);
    }
	private bool CheckColIceFloor(global::UnityEngine.Vector3 direction, float speed, out global::UnityEngine.Vector3 outVelocity) {
        if (CheckColNpcIceFloor(direction, speed))
        {
            outVelocity = Vector3.zero;
            return true;
        }

        outVelocity = CollisionUtility.CollideObstacle(worldPosition, 0.4f, direction, speed, out bool jump, out bool isCollided, out float dotAngle,
            Layer.Jump | Layer.Obstacle);
        if (isCollided && dotAngle > 0.5f)
            return true;

        var velocity = direction * speed;
        if (FieldGridCollision.CheckGriCollisionMoveEntity(out outVelocity, worldPosition, velocity, 0.4f, CheckGridCollision,
            FieldGridCollision.GridCollisionIgnoreDir.None) != FieldGridCollision.GridCollisionType.None)
            return true;

        outVelocity = velocity;
        return false;
    }
	private bool CheckColNpcIceFloor(global::UnityEngine.Vector3 direction, float speed) {
        var grid = PositionToGrid(worldPosition + direction * (speed + 0.4f));
        for (int i = 0; i < EntityManager.fieldCharacters.Length; i++)
        {
            if (EntityManager.fieldCharacters[i] == EntityManager.activeFieldPlayer)
                continue;

            if (!EntityManager.fieldCharacters[i].gameObject.activeInHierarchy)
                continue;

            var entityGrid = EntityManager.fieldCharacters[i].gridPosition;
            if (entityGrid.x == grid.x && entityGrid.y == grid.y)
                return true;
        }

        return false;
    }
	private float UpdateIceSpeed(float deltaTime) {
        float targetSpeed = IceSlidingLevel < 1 ? 0.001f : DataManager.FieldCommonParam[(int)ParamIndx.IceFloorAcc + IceSlidingLevel].param;
        float accel = DataManager.FieldCommonParam[(int)ParamIndx.IceFloorAcc].param * deltaTime;
        float diff = IceSlidingSpeed - targetSpeed;
        if (!(diff * diff <= accel * accel))
            targetSpeed = diff > 0.0f ? IceSlidingSpeed - accel : IceSlidingSpeed + accel;

        IceSlidingSpeed = targetSpeed;
        return IceSlidingSpeed;
    }
	private void CheckIceSlope() {
        var slopeDir = CheckIceSlopeFloor();
        if (slopeDir == default(Vector2Int))
            return;

        var target = Vec2ToVec3Position(GridToPosition(gridPosition + slopeDir), worldPosition.y);
        int axis = IceFloorDirection.x != 0.0f ? 2 : 0;
        target[axis] = IceFloorStartGridCenterPos[axis];
        IceSlopeDownMove.MoveTime(target, 0.6f);
        IceFloorState = IceFloorStateType.SlopeDown;
    }
	private global::UnityEngine.Vector2Int CheckIceSlopeFloor() {
        var center = Vec2ToVec3Position(GridToPosition(gridPosition), worldPosition.y);
        center.y += CollisionUtility.CollideGround(center, 30.0f, Layer.Ground);

        float height = CollisionUtility.CollideGround(center + Vector3.right * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.right : Vector2Int.left;

        height = CollisionUtility.CollideGround(center + Vector3.left * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.left : Vector2Int.right;

        height = CollisionUtility.CollideGround(center + Vector3.forward * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.down : Vector2Int.up;

        height = CollisionUtility.CollideGround(center + Vector3.back * 0.05f, 30.0f, Layer.Ground);
        if (height * height > 0.0001f)
            return height > 0.0f ? Vector2Int.up : Vector2Int.down;

        return default;
    }
	private bool IsIceGrid(global::UnityEngine.Vector2Int grid, float height) {
        GameManager.GetAttribute(grid, out int code, out int stop);
        var table = GameManager.GetAttributeTable(code);
        return table != null && AttributeID.MATR_IsIce(code);
    }
	private bool CheckMoveFloor(float deltaTime) {
        if (currentSequence == SequenceID.Active && PlayerWork.isPlayerInputActive)
        {
            // s0 still holds deltaTime at the call @01da5958 (CheckMoveFloorGrid never reads its float argument)
            NextMoveFloor = CheckMoveFloorGrid(gridPosition, deltaTime);
            return NextMoveFloor != MoveFloorType.None;
        }

        return false;
    }
	private global::FieldPlayerEntity.MoveFloorType CheckMoveFloorGrid(global::UnityEngine.Vector2Int grid, float height) {
        GameManager.GetAttribute(grid, out int code, out int stop);
        if (GameManager.GetAttributeTable(code) == null)
            return MoveFloorType.None;

        if (AttributeID.MATR_IsForceMoveLeft(code))
            return MoveFloorType.Left;

        if (AttributeID.MATR_IsForceMoveRight(code))
            return MoveFloorType.Right;

        if (AttributeID.MATR_IsForceMoveUp(code))
            return MoveFloorType.Back;

        return AttributeID.MATR_IsForceMoveDown(code) ? MoveFloorType.Front : MoveFloorType.None;
    }
	private void StartMoveFloor() {
        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI121, null);
        MoveFloorTime = 0.0f;
        PrevRotateOffset = 0.0f;
        MoveFloorRotate.FloatMove.EaseFunc = FieldFloatMove.EaseOutSin;
        MoveFloorRotate.SetObjectEntity(this);
        _animationPlayer.Play(Animation.Spin, 0.1f);
        _animationPlayer.SetAnimSpeed(1.0f);
        PlayerWork.isPlayerInputActive = false;
        nextSequence = SequenceID.MoveFloor;
    }
	private void EndMoveFloor() {
        MoveFloorRotate.Reset();
        PlayerWork.isPlayerInputActive = true;
        nextSequence = SequenceID.Active;
    }
	private void UpdateMoveFloor(float deltaTime) {
        MoveFloorRotate.Update(deltaTime);

        MoveFloorTime += deltaTime;
        if (!(MoveFloorTime < RotateAnimeOneCycleTime))
            MoveFloorTime -= RotateAnimeOneCycleTime;

        if (CurrentMoveFloor == MoveFloorType.None)
        {
            if (NextMoveFloor == MoveFloorType.None)
            {
                if (!MoveFloorRotate.IsBusy)
                    EndMoveFloor();

                return;
            }
        }
        else if (NextMoveFloor == MoveFloorType.None && gridPosition != oldGridPosition)
        {
            // CheckMoveFloorGrid never reads its height argument
            NextMoveFloor = CheckMoveFloorGrid(gridPosition, worldPosition.y);
        }

        float speed = DataManager.FieldCommonParam[(int)ParamIndx.MoveFloorSpd].param;
        if (NextMoveFloor != MoveFloorType.None)
        {
            float moveLength = speed * deltaTime;
            var target = Vec2ToVec3Position(GridToPosition(gridPosition), worldPosition.y);
            var diff = target - worldPosition;
            if (diff.sqrMagnitude > moveLength * moveLength)
            {
                diff = diff.normalized * moveLength;
            }
            else
            {
                CurrentMoveFloor = NextMoveFloor;
                NextMoveFloor = MoveFloorType.None;
            }

            moveVector = diff;
        }
        else
        {
            bool isHit = CheckColIceFloor(GetMoveFloorDirection(), speed * deltaTime, out Vector3 outVelocity);
            moveVector = outVelocity;
            if (isHit)
            {
                MoveFloorRotate.SetYawAngle(yawAngle + MoveFloorTime * -720.0f);
                MoveFloorRotate.MoveTime(yawAngle + -144.0f, 0.2f);
                _animationPlayer.SetAnimSpeed(0.0f);
                PlayIdle();
                CurrentMoveFloor = MoveFloorType.None;
            }
        }

        float rotateOffset = MoveFloorTime * -720.0f;
        if (PrevRotateOffset < rotateOffset)
            AudioManager.Instance.PlaySe(AK.EVENTS.S_FI121, null);

        PrevRotateOffset = rotateOffset;
    }
	private global::UnityEngine.Vector3 GetMoveFloorDirection() {
        switch (CurrentMoveFloor)
        {
            case MoveFloorType.Left:
                return Vector3.right;

            case MoveFloorType.Right:
                return Vector3.left;

            case MoveFloorType.Back:
                return Vector3.back;

            case MoveFloorType.Front:
                return Vector3.forward;

            default:
                return Vector3.zero;
        }
    }
	private bool CheckColMoveFloor(global::UnityEngine.Vector3 direction, float speed, out global::UnityEngine.Vector3 outVelocity) {
        return CheckColIceFloor(direction, speed, out outVelocity);
    }
