	private global::UnityEngine.Vector3 CalcCheckFrontGridDirection() {
        var forward = transform.forward;
        forward.y = 0.0f;
        return forward.normalized;
    }
	public bool CheckSwim() {
        if (!FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.BADGE_ID_C05))
            return false;

        var direction = CalcCheckFrontGridDirection();
        var frontGrid = PositionToGrid(worldPosition + direction * NaminoriCheckDistance);
        if (frontGrid.x != gridPosition.x && frontGrid.y != gridPosition.y)
            return false;

        GameManager.GetAttribute(frontGrid, out int code, out int stop);
        var table = GameManager.GetAttributeTable(code);
        if (table != null && !table.Water)
            return false;

        if (AttributeID.MATR_IsBridgeWater(code) && GameManager.IsHighAttribute(GameManager.GetAttributeExCodeRaw(frontGrid), worldPosition.y))
            return false;

        var velocity = CollisionUtility.CollideObstacle(worldPosition, 0.4f, direction, NaminoriCheckDistance, out bool jump, out bool isCollided,
            out float dotAngle, Layer.Obstacle);
        if (isCollided)
            return false;

        return FieldGridCollision.CheckGriCollisionMoveEntity(out Vector3 outVelocity, worldPosition, velocity, 0.4f, CheckGridCollisionCheckSwim,
            FieldGridCollision.GridCollisionIgnoreDir.None) == FieldGridCollision.GridCollisionType.None;
    }
	private global::Dpr.FieldGridCollision.GridCollisionType CheckGridCollisionCheckSwimCore(global::UnityEngine.Vector2Int grid) {
        GameManager.GetAttribute(grid, out int code, out int stop);
        if (!CanEntryAttributeCommon(code, stop))
            return FieldGridCollision.GridCollisionType.NoEntry;

        return EvDataManager.Instanse.CheckEventObjectGrid(grid.x, grid.y, worldPosition.y) ?
            FieldGridCollision.GridCollisionType.Npc : FieldGridCollision.GridCollisionType.None;
    }
	public global::UnityEngine.Vector3 CalcSwimTargetPosition() {
        var direction = CalcCheckFrontGridDirection();
        var frontPos = worldPosition + direction * NaminoriCheckDistance;
        var frontGrid = PositionToGrid(frontPos);
        var targetPos = Vec2ToVec3Position(GridToPosition(frontGrid), frontPos.y);

        var startPos = frontPos;
        if (gridPosition.x != frontGrid.x)
            startPos.x = targetPos.x;
        else if (gridPosition.y != frontGrid.y)
            startPos.z = targetPos.z;

        if (ZoneWork.IsUnderGround(PlayerWork.zoneID))
            targetPos.y = -0.5f;
        else
            targetPos.y += CollisionUtility.CollideGround(targetPos, 0.5f, Layer.Ground);

        var moveVec = startPos - targetPos;
        moveVec.y = 0.0f;
        float length = moveVec.magnitude;
        if (!(length < 0.0001f))
        {
            var velocity = CollisionUtility.CollideObstacle(targetPos, 0.4f, moveVec.normalized, length, out bool jump, out bool isCollided,
                out float dotAngle, Layer.Obstacle);
            CheckGridCollisionCalcSwim.waterPositionY = frontPos.y;

            if (FieldGridCollision.CheckGriCollisionMoveEntity(out Vector3 outVelocity, targetPos, velocity, 0.4f, CheckGridCollisionCalcSwim,
                FieldGridCollision.GridCollisionIgnoreDir.None) == FieldGridCollision.GridCollisionType.None)
                targetPos += velocity;
            else if (!isCollided)
                targetPos += outVelocity;
        }

        return new Vector3(targetPos.x, targetPos.y + NaminoriWaterSurfaceOfs, targetPos.z);
    }
	private global::Dpr.FieldGridCollision.GridCollisionType CheckGridCollisionCalcSwimCore(global::UnityEngine.Vector2Int grid, float waterPositionY) {
        if (!CanEntryAttribute(grid, waterPositionY, false, true))
            return FieldGridCollision.GridCollisionType.NoEntry;

        return EvDataManager.Instanse.CheckEventObjectGrid(grid.x, grid.y, worldPosition.y) ?
            FieldGridCollision.GridCollisionType.Npc : FieldGridCollision.GridCollisionType.None;
    }
	private bool UpdateSwim(float deltaTime) {
        Vector2 stick = GameController.analogStickL;
        if (stick.x * stick.x + stick.y * stick.y < 0.01f)
            stick = GameController.digitalPad;

        if (stick.x * stick.x + stick.y * stick.y > 0.01f)
        {
            if (CheckEndSwim(stick))
            {
                RequestEndSwimEvent();
                return true;
            }

            if (CheckWaterfallDown(stick))
            {
                WaterfallDownEvent();
                return true;
            }
        }

        if (FieldInput.PushA() && CheckWaterfallUp())
        {
            WaterfallUpEvent();
            return true;
        }

        return false;
    }
	private bool CheckEndSwim(global::UnityEngine.Vector2 inputDir) {
        var direction = CalcCheckFrontGridDirection();
        var input = new Vector3(-inputDir.x, 0.0f, -inputDir.y);
        // 0.9396926f = cos(20 deg) (0x3f708fb2 @01db3098)
        if (Vector3.Dot(input, direction) < 0.9396926f)
            return false;

        var frontGrid = PositionToGrid(worldPosition + direction * NaminoriCheckDistance);
        if (frontGrid.x != gridPosition.x && frontGrid.y != gridPosition.y)
            return false;

        GameManager.GetAttribute(frontGrid, out int code, out int stop);
        bool isBridgeWater = AttributeID.MATR_IsBridgeWater(code);

        GameManager.GetAttribute(frontGrid, out int landCode, out int landStop);
        if (!CanEntryAttributeCommon(landCode, landStop))
            return false;

        var table = GameManager.GetAttributeTable(landCode);
        if (table != null && table.Water)
            return false;

        if (isBridgeWater && AttributeID.MATR_IsBridge(landCode))
            return false;

        var velocity = CollisionUtility.CollideObstacle(worldPosition, 0.4f, direction, NaminoriCheckDistance, out bool jump, out bool isCollided,
            out float dotAngle, Layer.Obstacle);
        if (isCollided)
            return false;

        return FieldGridCollision.CheckGriCollisionMoveEntity(out Vector3 outVelocity, worldPosition, velocity, 0.4f, CheckGridCollisionEndSwim,
            FieldGridCollision.GridCollisionIgnoreDir.None) == FieldGridCollision.GridCollisionType.None;
    }
	private global::Dpr.FieldGridCollision.GridCollisionType CheckGridCollisionEndSwimCore(global::UnityEngine.Vector2Int grid) {
        GameManager.GetAttribute(grid, out int code, out int stop);
        if (!CanEntryAttributeCommon(code, stop))
            return FieldGridCollision.GridCollisionType.NoEntry;

        return EvDataManager.Instanse.CheckEventObjectGrid(grid.x, grid.y, worldPosition.y) ?
            FieldGridCollision.GridCollisionType.Npc : FieldGridCollision.GridCollisionType.None;
    }
